# 方式 3：LLM-as-Moderator（最智能，处理边界情况）
class LLMModerator:
    """用 LLM 理解上下文语义来审核内容"""

    async def moderate(self, text, context=None):
        prompt = f"""
        你是内容安全审核员。请评估以下内容是否安全。

        上下文：{context or '无'}
        待审内容：{text}

        评估维度：
        1. 暴力/威胁 (0-1)
        2. 仇恨/歧视 (0-1)
        3. 色情/成人 (0-1)
        4. 自伤/自杀 (0-1)
        5. 违法/犯罪 (0-1)

        注意上下文：医疗讨论中的"注射"不是暴力，
        安全教育中的"攻击方式"是合理讨论。

        输出 JSON：{{"safe": bool, "scores": {{...}}, "reasoning": "..."}}
        """
        return await self.judge.invoke(prompt)
